package com.gameaggregator.tenantservice.api;
import static com.gameaggregator.tenantservice.api.TenantDtos.*; import com.gameaggregator.tenantservice.application.TenantService; import com.gameaggregator.platform.core.common.web.ApiResponse; import jakarta.validation.Valid; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.web.bind.annotation.*;
@RestController public class TenantController { private final TenantService service; public TenantController(TenantService s){service=s;} private UUID user(Jwt j){return UUID.fromString(j.getSubject());} @PostMapping("/tenants") @ResponseStatus(HttpStatus.CREATED) public ApiResponse<TenantView> create(@AuthenticationPrincipal Jwt j,@Valid @RequestBody CreateTenant r){return ApiResponse.success(service.create(user(j),r));} @PostMapping("/tenants/{tenantId}/organizations") public ApiResponse<OrganizationView> org(@AuthenticationPrincipal Jwt j,@PathVariable UUID tenantId,@Valid @RequestBody CreateOrganization r){return ApiResponse.success(service.organization(user(j),tenantId,r));} @PostMapping("/tenants/{tenantId}/members") public ApiResponse<MemberView> member(@AuthenticationPrincipal Jwt j,@PathVariable UUID tenantId,@Valid @RequestBody AddMember r){return ApiResponse.success(service.addMember(user(j),tenantId,r));} @PostMapping("/tenants/{tenantId}/roles") public ApiResponse<RoleView> role(@AuthenticationPrincipal Jwt j,@PathVariable UUID tenantId,@Valid @RequestBody CreateRole r){return ApiResponse.success(service.createRole(user(j),tenantId,r));} @PutMapping("/tenants/{tenantId}/members/{memberId}/roles/{roleId}") public ApiResponse<Map<String,Boolean>> assign(@AuthenticationPrincipal Jwt j,@PathVariable UUID tenantId,@PathVariable UUID memberId,@PathVariable UUID roleId){service.assignRole(user(j),tenantId,memberId,roleId);return ApiResponse.success(Map.of("assigned",true));} @GetMapping("/internal/access-context") public ApiResponse<AccessContext> access(@AuthenticationPrincipal Jwt j,@RequestParam UUID tenantId){return ApiResponse.success(service.access(user(j),tenantId));} }
